const bySlug = new Map(manufacturers.map((item) => [item.slug, item]));
export function manufacturerBySlug(slug: string) {
  return bySlug.get(slug);
}

export function factoryFacts(item: Manufacturer) {
  const focus = item.line === "burner" ? "Горелки" : item.line === "air" ? "Воздухонагреватели" : "Промышленные котлы";
  return [
    { label: "Наименование", value: item.name },
    { label: "Год основания", value: "Не указано" },
    { label: "Специализация", value: `${focus}, ${item.place}` },
  ];
}
